/** Swing is the sum of the torque of the people followed; zero without allies, absent while any ally's torque is absent. */
public Integer getSwing() {
    int sum = 0;
    for (Person ally : getAllies()) {
        Integer torque = ally.getTorque();
        if (torque == null) {
            return null;
        }
        sum += torque;
    }
    return sum;
}

